def validate(n: int) -> bool:
    """
    檢查整數 n 中每個「出現過」的數字頻率是否 <= 該數字本身。
    Precondition (依題目合約): isinstance(n, int) and n >= 0
    """
    freq = {}
    for ch in str(n):
        freq[ch] = freq.get(ch, 0) + 1

    return all(count <= int(digit) for digit, count in freq.items())
